import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { ok, fail } from './result.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text: number/DRAFT, customer, line items with discounts,
 * VAT, voucher (if any), total, due date (if any), and amount paid (if any).
 * All amounts are formatted with formatEuros().
 * @param {{ customerId: string, number?: string, lines: Array<any>, dueDate?: string, voucher?: any, payments?: Array<any> }}
 */
export function renderInvoiceText(invoice) {
  // Look up customer
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Build lines
  const lines = [];

  // Invoice number or DRAFT
  lines.push(invoice.number ?? 'DRAFT');

  // Customer name
  lines.push(customer.name);

  // Invoice lines with discount info
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    let lineText = `${line.qty} ${line.name} ${formatEuros(line.unitPrice)} ${formatEuros(total)}`;

    // Add discount info if line has a discount
    if (line.discountPercent && line.discountPercent > 0) {
      const discountAmount = total * (line.discountPercent / 100);
      lineText += ` (${line.discountPercent}% off: -${formatEuros(discountAmount)})`;
    }

    lines.push(lineText);
  }

  // VAT and Total
  const totals = invoiceTotals(invoice);
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Voucher (if any)
  if (invoice.voucher) {
    lines.push(`Voucher: -${formatEuros(invoice.voucher.amount)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date (if any)
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Amount paid (if any)
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return ok(lines.join('\n'));
}

