import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText renders a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = renderInvoiceText(inv);
  assert.equal(r2.ok, true);
  const text = r2.value;
  assert.ok(text.includes('DRAFT'));
  assert.ok(text.includes('Northwind Studio'));
  assert.ok(text.includes('5 Design work (hour)'));
  assert.ok(text.includes('€85.00'));
  assert.ok(text.includes('€425.00'));
  assert.ok(text.includes('VAT: €84.79'));
  assert.ok(text.includes('Total: €488.54'));
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = renderInvoiceText(issued);
  assert.equal(r3.ok, true);
  const text = r3.value;
  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes('Northwind Studio'));
});

test('renderInvoiceText renders multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const inv = r.value;

  const r2 = renderInvoiceText(inv);
  assert.equal(r2.ok, true);
  const text = r2.value;
  const lines = text.split('\n');
  // Lines include: DRAFT + customer + 2 lines (with discount info) + VAT + total
  assert.ok(lines.length >= 6);
  assert.ok(text.includes('5 Design work (hour)'));
  assert.ok(text.includes('3 Development (hour)'));
  assert.ok(text.includes('VAT: €141.65'));
  assert.ok(text.includes('Total: €816.15'));
});

test('renderInvoiceText shows line totals correctly', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });
  const inv = r.value;

  const r2 = renderInvoiceText(inv);
  const text = r2.value;
  // LOGO-PACK: €1,200.00 each, 2 × = €2,400.00
  assert.ok(text.includes('2 Logo package €1,200.00 €2,400.00'));
});

test('renderInvoiceText formats all amounts with formatEuros', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'ICON-SET', qty: 8 },
      { sku: 'STICKER', qty: 5 },
    ],
  });
  const inv = r.value;

  const r2 = renderInvoiceText(inv);
  const text = r2.value;
  // ICON-SET: €9.80 each, 8 × = €78.40
  // STICKER: €0.50 each, 5 × = €2.50
  // Subtotal: €80.90, 2.5% tier discount = €2.0225, base = €78.8775, 21% VAT = €16.56 → €17
  // Total: €80.90 - €2.02 + €17.00 = €95.88
  assert.ok(text.includes('€9.80'));
  assert.ok(text.includes('€78.40'));
  assert.ok(text.includes('€0.50'));
  assert.ok(text.includes('€2.50'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText reports CUSTOMER_NOT_FOUND', () => {
  const inv = {
    customerId: 'C-999',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const r = renderInvoiceText(inv);
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('renderInvoiceText produces multi-line text', () => {
  const r = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  const inv = r.value;

  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = renderInvoiceText(issued);
  const text = r3.value;
  const lines = text.split('\n');
  assert.equal(lines[0], 'INV-2026-0001');
  assert.equal(lines[1], 'Smith, Jones & Partners');
  assert.ok(lines[2].includes('8 Design work (hour)'));
  assert.ok(lines[3].includes('5 Development (hour)'));
  assert.ok(lines[4].includes('VAT:'));
  assert.ok(lines[5].includes('Total:'));
});

test('renderInvoiceText shows line discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  const inv = r.value;

  const r2 = renderInvoiceText(inv);
  const text = r2.value;
  // Should show the line with discount info
  // lineTotal: 42500 (€425.00), discount: 10% = 4250 cents (€42.50)
  assert.ok(text.includes('(10% off:'));
  assert.ok(text.includes('-€42.50'));
});

test('renderInvoiceText does not show discount for lines without one', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = renderInvoiceText(inv);
  const text = r2.value;
  // Should not show discount info for standard tier (0% discount)
  const lines = text.split('\n');
  const lineItem = lines.find(l => l.includes('Design work'));
  assert.ok(!lineItem.includes('(0% off:'));
});

test('renderInvoiceText shows voucher before total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const withVoucher = applyVoucher(inv, { code: 'PROMO', amount: 5000 }).value;

  const r2 = renderInvoiceText(withVoucher);
  const text = r2.value;
  const lines = text.split('\n');
  // Find voucher and total lines
  const voucherLine = lines.findIndex(l => l.includes('Voucher:'));
  const totalLine = lines.findIndex(l => l.includes('Total:'));
  assert.ok(voucherLine > -1, 'Voucher line should exist');
  assert.ok(totalLine > voucherLine, 'Voucher should come before total');
  assert.ok(text.includes('Voucher: -€50.00'));
});

test('renderInvoiceText shows due date when available', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const issued = issueInvoice(inv, []).value;

  const r2 = renderInvoiceText(issued);
  const text = r2.value;
  assert.ok(text.includes('Due: 2026-11-06'));
});

test('renderInvoiceText does not show due date for draft', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = renderInvoiceText(inv);
  const text = r2.value;
  // Draft invoices don't have dueDate, so this line shouldn't appear
  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows amount paid when invoice has payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 20000, date: '2026-10-15' }).value;

  const r2 = renderInvoiceText(partial);
  const text = r2.value;
  assert.ok(text.includes('Paid: €200.00'));
});

test('renderInvoiceText does not show paid line for unpaid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const issued = issueInvoice(inv, []).value;

  const r2 = renderInvoiceText(issued);
  const text = r2.value;
  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText shows total paid with multiple payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const issued = issueInvoice(inv, []).value;
  const partial1 = recordPayment(issued, { amount: 10000, date: '2026-10-10' }).value;
  const partial2 = recordPayment(partial1, { amount: 15000, date: '2026-10-15' }).value;

  const r2 = renderInvoiceText(partial2);
  const text = r2.value;
  // Total paid should be 25000 cents = €250.00
  assert.ok(text.includes('Paid: €250.00'));
});

test('renderInvoiceText shows all new fields in correct order', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const withVoucher = applyVoucher(inv, { code: 'TEST', amount: 3000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const partial = recordPayment(issued, { amount: 25000, date: '2026-10-15' }).value;

  const r2 = renderInvoiceText(partial);
  const text = r2.value;
  const lines = text.split('\n');

  // Check order: number, customer, line items, VAT, voucher, total, due, paid
  assert.equal(lines[0], 'INV-2026-0001');
  assert.equal(lines[1], 'Northwind Studio');
  // Line with discount info should be present
  assert.ok(lines[2].includes('Design work'));
  // Find VAT, Voucher, Total, Due, Paid in order
  let vat_idx = lines.findIndex(l => l.includes('VAT:'));
  let voucher_idx = lines.findIndex(l => l.includes('Voucher:'));
  let total_idx = lines.findIndex(l => l.startsWith('Total:'));
  let due_idx = lines.findIndex(l => l.startsWith('Due:'));
  let paid_idx = lines.findIndex(l => l.startsWith('Paid:'));

  assert.ok(vat_idx < voucher_idx, 'VAT should come before voucher');
  assert.ok(voucher_idx < total_idx, 'Voucher should come before total');
  assert.ok(total_idx < due_idx, 'Total should come before due');
  assert.ok(due_idx < paid_idx, 'Due should come before paid');
});

test('renderInvoiceText with line discounts and voucher', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 },
    ],
  });
  const inv = r.value;
  const withVoucher = applyVoucher(inv, { code: 'SAVE', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const r2 = renderInvoiceText(issued);
  const text = r2.value;

  // Check for both discount types
  assert.ok(text.includes('(5% off:')); // First line has tier discount
  assert.ok(text.includes('(15% off:')); // Second line has explicit discount
  assert.ok(text.includes('Voucher: -€50.00'));
  assert.ok(text.includes('Due:'));
});

test('renderInvoiceText renders fully paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 48854, date: '2026-10-15' }).value;

  const r2 = renderInvoiceText(paid);
  const text = r2.value;
  const lines = text.split('\n');

  // Should have all sections
  assert.ok(lines.some(l => l.includes('INV-2026-0001')));
  assert.ok(lines.some(l => l.includes('Northwind Studio')));
  assert.ok(lines.some(l => l.includes('Design work')));
  assert.ok(lines.some(l => l.includes('VAT:')));
  assert.ok(lines.some(l => l.startsWith('Total:')));
  assert.ok(lines.some(l => l.startsWith('Due:')));
  assert.ok(lines.some(l => l.startsWith('Paid:')));

  // Paid amount should match invoice total
  assert.ok(text.includes('Paid: €488.54'));
});

